import {test} from 'node:test';
import assert from 'node:assert/strict';
import {shippingFee} from '../src/shipping.mjs';
test('hidden check', () => {
  assert.equal(shippingFee(69999, 'seoul'), 3000);
  assert.equal(shippingFee(70000, 'seoul'), 0);
  assert.equal(shippingFee(70000, 'jeju'), 4500);
});
